using namespace Monstey;
using Monstey_U64=std::uint64_t;
using Monstey_Image=std::vector<std::uint8_t>;
static Monstey_Json Monstey_Rows=Monstey_Json::array();
static std::string Monstey_Current;
static Monstey_U64 Monstey_Checks=0,Monstey_Images=0,Monstey_Bytes=0;
void Monstey_Check(bool ok,const std::string &why){++Monstey_Checks;if(!ok)throw std::runtime_error(Monstey_Current+": "+why);}
void Monstey_Put(Monstey_Image &image,Monstey_U64 base,Monstey_U64 address,Monstey_U64 value){for(std::size_t i=0;i<8;++i)image.at(static_cast<std::size_t>(address-base)+i)=static_cast<std::uint8_t>(value>>(i*8));}
Monstey_U64 Monstey_Get(const Monstey_Image &image,Monstey_U64 base,Monstey_U64 address){Monstey_U64 value=0;for(std::size_t i=0;i<8;++i)value|=Monstey_U64(image.at(static_cast<std::size_t>(address-base)+i))<<(i*8);return value;}
struct Monstey_Fixture {
 Monstey_Image image=Monstey_Image(4096,std::uint8_t{0xD3}),expected=image;
 Monstey_U64 base=0;
 Monstey_GadbManagerPrimitiveBindings bindings{std::nullopt,0x80,0x88};
 Monstey_GadbManagerEnterProjectionServices services;
 Monstey_GadbBufferedResult incoming{0xA0123456789BCDEFULL,0xB0123456789BCDEFULL};
 Monstey_U64 x8=0xC0123456789BCDEFULL,x9=0xD0123456789BCDEFULL;
 Monstey_GadbManagerEnterProjectionResult declared{0xE2123456789BCDEFULL,0xE8123456789BCDEFULL,0xE9123456789BCDEFULL};
 std::vector<std::string> events;
 Monstey_GadbBinderMemory Monstey_Memory(){return {base,image};}
 void Monstey_Snapshot(){expected=image;}
 void Monstey_CompareImage(){if(image!=expected){std::size_t i=0;while(i<image.size()&&image[i]==expected[i])++i;Monstey_Check(false,"whole image byte "+std::to_string(i));}Monstey_Check(true,"whole image");++Monstey_Images;Monstey_Bytes+=image.size();}
 void Monstey_Finish(const Monstey_GadbManagerGuardProjectedResult &r,Monstey_U64 guard,const Monstey_GadbManagerEnterProjectionResult &want){
  Monstey_Check(r.raw.rax==guard&&r.raw.rdx==want.rdx,"concrete Raw2 G/E2");Monstey_Check(r.post_enter_r8==want.r8&&r.post_enter_r9==want.r9,"actual full64 E8/E9");Monstey_CompareImage();
  auto eventsJson=Monstey_Json::array();for(const auto &e:events)eventsJson.as_array().push_back(e);
  Monstey_Rows.as_array().push_back(Monstey_Json::object({{"name",Monstey_Current},{"kind","normal"},{"rax",std::to_string(r.raw.rax)},{"rdx",std::to_string(r.raw.rdx)},{"r8",std::to_string(r.post_enter_r8)},{"r9",std::to_string(r.post_enter_r9)},{"events",eventsJson}}));
 }
 void Monstey_Fault(){Monstey_CompareImage();Monstey_Rows.as_array().push_back(Monstey_Json::object({{"name",Monstey_Current},{"kind","expected_fault"}}));}
 Monstey_GadbManagerGuardProjectedResult Monstey_Call(Monstey_U64 g,Monstey_U64 lock){return Monstey_GadbConstructManagerGuardProjected(Monstey_Memory(),g,lock,incoming,x8,x9,bindings,services);}
 void Monstey_Request(const Monstey_GadbManagerEnterProjectionCall &c,Monstey_U64 lock,Monstey_U64 target){
  Monstey_Check(c.base.operation==Monstey_GadbManagerSyncOperation::enter&&c.base.native_site==0x14114BA9FULL,"actual Enter operation/native site");
  Monstey_Check(c.base.slot_identity==bindings.enter_cell&&c.base.target_identity==target&&c.base.critical_section==lock,"actual live slot/target/lock");
  Monstey_Check(c.base.incoming.rax==incoming.rax&&c.base.incoming.rdx==lock,"real incoming Raw2 with own RDX assignment");
  Monstey_Check(c.incoming_r8==x8&&c.incoming_r9==x9,"full64 X8/X9 forwarded");
 }
};
template<class F> void Monstey_MemoryFault(Monstey_Fixture &x,F call,Monstey_U64 address,bool writing){bool seen=false;try{call();}catch(const Monstey_GadbBufferedMemoryFault &e){seen=true;Monstey_Check(e.address==address&&e.width==8&&e.writing==writing,"exact range first-fault");}Monstey_Check(seen,"expected memory fault");x.Monstey_Fault();}
void Monstey_NormalCases(){
 for(int alias=-8;alias<=8;++alias)for(int pattern=0;pattern<4;++pattern){Monstey_Current="GP01/02 normal alias="+std::to_string(alias)+" pattern="+std::to_string(pattern);Monstey_Fixture x;
  const Monstey_U64 guard=alias==-8?0:alias==8?0x100:static_cast<Monstey_U64>(0x80+alias);
  const auto lock=pattern==0?Monstey_U64{0}:pattern==1?~Monstey_U64{0}:pattern==2?Monstey_U64{0x8877665544332211ULL}:Monstey_U64{0x0123456789ABCDEFULL};
  x.incoming.rax^=static_cast<Monstey_U64>(pattern);x.x8^=static_cast<Monstey_U64>(alias+8);x.x9^=static_cast<Monstey_U64>(pattern)*0x100000000ULL;
  Monstey_Put(x.image,x.base,x.bindings.enter_cell,pattern==0?0:0x1122334455667788ULL);x.Monstey_Snapshot();Monstey_Put(x.expected,x.base,guard,lock);
  const auto target=Monstey_Get(x.expected,x.base,x.bindings.enter_cell);x.services.enter=[&,guard,lock,target](Monstey_GadbBinderMemory,const Monstey_GadbManagerEnterProjectionCall &c){x.events.push_back("enter");x.Monstey_Request(c,lock,target);Monstey_Check(Monstey_Get(x.image,x.base,guard)==lock,"Gstore precedes current call");Monstey_Put(x.image,x.base,0x300,x.declared.r8);Monstey_Put(x.expected,x.base,0x300,x.declared.r8);if(pattern==3){Monstey_Put(x.image,x.base,guard,0xBADBEEF);Monstey_Put(x.expected,x.base,guard,0xBADBEEF);}return x.declared;};
  x.Monstey_Finish(x.Monstey_Call(guard,lock),guard,x.declared);Monstey_Check(x.events.size()==1,"exactly one primitive call");
 }
 {Monstey_Current="GP02 max address valid eight-byte store";Monstey_Fixture x;x.image.assign(256,std::uint8_t{0xC7});x.base=~Monstey_U64{0}-255;x.bindings.enter_cell=x.base+8;x.bindings.leave_cell=x.base+16;const auto guard=~Monstey_U64{0}-7;const auto lock=0xABCDEF0123456789ULL;Monstey_Put(x.image,x.base,x.bindings.enter_cell,0);x.Monstey_Snapshot();Monstey_Put(x.expected,x.base,guard,lock);x.services.enter=[&](Monstey_GadbBinderMemory,const Monstey_GadbManagerEnterProjectionCall &c){x.Monstey_Request(c,lock,0);return x.declared;};x.Monstey_Finish(x.Monstey_Call(guard,lock),guard,x.declared);}
}
void Monstey_FirstFaultCases(){
 for(int invalid=0;invalid<8;++invalid){Monstey_Current="GP02 store whole-width tail "+std::to_string(invalid);Monstey_Fixture x;const auto guard=x.image.size()-static_cast<std::size_t>(invalid);x.bindings.enter_cell=~Monstey_U64{0};x.Monstey_Snapshot();Monstey_MemoryFault(x,[&]{static_cast<void>(x.Monstey_Call(guard,0x44));},guard,true);}
 {Monstey_Current="GP02 address overflow store first";Monstey_Fixture x;x.Monstey_Snapshot();Monstey_MemoryFault(x,[&]{static_cast<void>(x.Monstey_Call(~Monstey_U64{0}-6,0x44));},~Monstey_U64{0}-6,true);}
 for(int missing=0;missing<8;++missing){Monstey_Current="GP02 livecell whole-width tail "+std::to_string(missing);Monstey_Fixture x;x.bindings.enter_cell=x.image.size()-static_cast<std::size_t>(missing);x.Monstey_Snapshot();Monstey_Put(x.expected,0,0x100,0xABCDEF);Monstey_MemoryFault(x,[&]{static_cast<void>(x.Monstey_Call(0x100,0xABCDEF));},x.bindings.enter_cell,false);}
 for(bool alias:{false,true})for(bool zero:{false,true}){Monstey_Current="GP02 missing service after store/livecell "+std::to_string(alias)+std::to_string(zero);Monstey_Fixture x;const Monstey_U64 guard=alias?0x80:0x100,lock=zero?0:0xAA55BB66CC77DD88ULL;Monstey_Put(x.image,0,x.bindings.enter_cell,zero?0:0xCCEE);x.Monstey_Snapshot();Monstey_Put(x.expected,0,guard,lock);const auto target=Monstey_Get(x.expected,0,x.bindings.enter_cell);bool seen=false;try{static_cast<void>(x.Monstey_Call(guard,lock));}catch(const Monstey_GadbManagerPrimitiveBoundaryFault &e){seen=true;Monstey_Check(e.kind==Monstey_GadbManagerPrimitiveBoundaryKind::missing_sync_service&&e.native_site==0x14114BA9FULL&&e.address==x.bindings.enter_cell&&e.width==8&&e.slot_identity==x.bindings.enter_cell&&e.target_identity==target&&e.argument==lock,"exact unchanged M1 boundary diagnostic");}Monstey_Check(seen,"missing service boundary");x.Monstey_Fault();}
}
struct Monstey_SharedExceptionToken {Monstey_U64 value;std::string label;};
struct Monstey_TypedException : std::runtime_error {std::shared_ptr<Monstey_SharedExceptionToken> token;explicit Monstey_TypedException(std::shared_ptr<Monstey_SharedExceptionToken> t):std::runtime_error("provider label"),token(std::move(t)){} };
struct Monstey_RetireWitness {Monstey_Fixture *x=nullptr;int *retired=nullptr;~Monstey_RetireWitness(){if(x){++*retired;Monstey_Put(x->image,0,0x388,0xDEAD1234);Monstey_Put(x->expected,0,0x388,0xDEAD1234);x->events.push_back("retired");}}};
void Monstey_ExceptionCases(){for(int n=0;n<4;++n){Monstey_Current="GP02/03 typed provider exception "+std::to_string(n);Monstey_Fixture x;auto token=std::make_shared<Monstey_SharedExceptionToken>(Monstey_SharedExceptionToken{0xFEDCBA9876543210ULL+static_cast<Monstey_U64>(n),"owned-token"});Monstey_Put(x.image,0,x.bindings.enter_cell,0xAA);x.Monstey_Snapshot();Monstey_Put(x.expected,0,0x100,0xBEEFULL);x.services.enter=[&,token](Monstey_GadbBinderMemory,const Monstey_GadbManagerEnterProjectionCall &c)->Monstey_GadbManagerEnterProjectionResult{x.Monstey_Request(c,0xBEEF,0xAA);Monstey_Put(x.image,0,0x320,token->value);Monstey_Put(x.expected,0,0x320,token->value);if(n&1)x.services.enter={};throw Monstey_TypedException(token);};bool seen=false;try{static_cast<void>(x.Monstey_Call(0x100,0xBEEF));}catch(const Monstey_TypedException &e){seen=true;Monstey_Check(e.token==token&&e.token->value==0xFEDCBA9876543210ULL+static_cast<Monstey_U64>(n)&&e.token->label=="owned-token"&&std::string(e.what())=="provider label","declared dynamic exception type/sharedtoken/value/label");}Monstey_Check(seen,"typed exception propagated");x.Monstey_Fault();}}
void Monstey_CurrentCases(){
 {Monstey_Current="GP03 mutable current holder across calls";Monstey_Fixture x;int count=0;Monstey_Put(x.image,0,0x80,0);x.Monstey_Snapshot();x.services.enter=[&,state=0](Monstey_GadbBinderMemory,const Monstey_GadbManagerEnterProjectionCall &c)mutable{++state;++count;x.Monstey_Request(c,0x55,static_cast<Monstey_U64>(state-1));Monstey_Put(x.image,0,0x80,static_cast<Monstey_U64>(state));Monstey_Put(x.expected,0,0x80,static_cast<Monstey_U64>(state));return Monstey_GadbManagerEnterProjectionResult{x.declared.rdx+static_cast<Monstey_U64>(state),x.declared.r8,x.declared.r9};};for(int i=1;i<=4;++i){const auto guard=0x100u+static_cast<Monstey_U64>(i)*8;Monstey_Put(x.expected,0,guard,0x55);auto want=x.declared;want.rdx+=static_cast<Monstey_U64>(i);x.Monstey_Finish(x.Monstey_Call(guard,0x55),guard,want);}Monstey_Check(count==4,"persistent mutable target state");}
 {Monstey_Current="GP03 selfclear then exact missing subsequent consumption";Monstey_Fixture x;Monstey_Put(x.image,0,0x80,0xAA);x.Monstey_Snapshot();Monstey_Put(x.expected,0,0x100,0x55);int retired=0;auto witness=std::make_shared<Monstey_RetireWitness>();witness->x=&x;witness->retired=&retired;x.services.enter=[&,witness](Monstey_GadbBinderMemory,const Monstey_GadbManagerEnterProjectionCall &){x.events.push_back("enter");x.services.enter={};Monstey_Put(x.image,0,0x80,0);Monstey_Put(x.expected,0,0x80,0);return x.declared;};witness.reset();const auto r=x.Monstey_Call(0x100,0x55);Monstey_Check(retired==1,"real retirement observable by caller return");x.Monstey_Finish(r,0x100,x.declared);Monstey_Current="GP03 subsequent call after selfclear";Monstey_Put(x.expected,0,0x180,0x66);bool seen=false;try{static_cast<void>(x.Monstey_Call(0x180,0x66));}catch(const Monstey_GadbManagerPrimitiveBoundaryFault &e){seen=true;Monstey_Check(e.native_site==0x14114BA9FULL&&e.target_identity==0&&e.argument==0x66,"current cleared holder diagnosed at next consumption");}Monstey_Check(seen,"expected cleared holder fault");x.Monstey_Fault();}
 {Monstey_Current="GP03 replacement and reentry retain active target";Monstey_Fixture x;Monstey_Put(x.image,0,0x80,0xAA);x.Monstey_Snapshot();Monstey_Put(x.expected,0,0x100,0x55);int retired=0,newcalls=0;auto witness=std::make_shared<Monstey_RetireWitness>();witness->x=&x;witness->retired=&retired;x.services.enter=[&,witness](Monstey_GadbBinderMemory mem,const Monstey_GadbManagerEnterProjectionCall &outer){x.events.push_back("old");Monstey_Check(outer.base.incoming.rax==x.incoming.rax,"old active real RAX");x.services.enter=[&](Monstey_GadbBinderMemory,const Monstey_GadbManagerEnterProjectionCall &nested){++newcalls;x.events.push_back("new");Monstey_Check(nested.base.target_identity==0xBB&&nested.base.critical_section==0x66&&nested.incoming_r8==0x8877665544332211ULL&&nested.incoming_r9==0x7766554433221100ULL,"reentrant current DTO");return Monstey_GadbManagerEnterProjectionResult{0xE200000000000001ULL,0xE800000000000002ULL,0xE900000000000003ULL};};Monstey_Put(x.image,0,0x80,0xBB);Monstey_Put(x.expected,0,0x80,0xBB);Monstey_Put(x.expected,0,0x180,0x66);const auto inner=Monstey_GadbConstructManagerGuardProjected(mem,0x180,0x66,{0x1122,0x3344},0x8877665544332211ULL,0x7766554433221100ULL,x.bindings,x.services);Monstey_Check(inner.raw.rax==0x180&&inner.raw.rdx==0xE200000000000001ULL&&inner.post_enter_r8==0xE800000000000002ULL&&inner.post_enter_r9==0xE900000000000003ULL&&retired==0,"new target result, old remains active during reentry");return x.declared;};witness.reset();const auto r=x.Monstey_Call(0x100,0x55);Monstey_Check(retired==1&&newcalls==1,"one real active-target retirement and nested consumption");x.Monstey_Finish(r,0x100,x.declared);}
}
void Monstey_OldProjectionCases(){for(int i=0;i<24;++i){Monstey_Current="GP04 real old/new Raw2 subset "+std::to_string(i);Monstey_Fixture x,y;const auto guard=i%3==0?0x80u:0x100u;const auto lock=0xAA55000000000000ULL+static_cast<Monstey_U64>(i);const auto actualOldRax=0x7123000000000000ULL+static_cast<Monstey_U64>(i);Monstey_Put(x.image,0,0x80,static_cast<Monstey_U64>(i));y.image=x.image;x.Monstey_Snapshot();y.Monstey_Snapshot();Monstey_Put(x.expected,0,guard,lock);Monstey_Put(y.expected,0,guard,lock);const auto target=Monstey_Get(x.expected,0,0x80);x.services.enter=[&](Monstey_GadbBinderMemory,const Monstey_GadbManagerEnterProjectionCall &c){x.Monstey_Request(c,lock,target);Monstey_Put(x.image,0,0x300,x.declared.rdx);Monstey_Put(x.expected,0,0x300,x.declared.rdx);return x.declared;};Monstey_GadbManagerPrimitiveServices old;old.sync=[&](Monstey_GadbBinderMemory,const Monstey_GadbManagerSyncCall &c){Monstey_Check(c.operation==Monstey_GadbManagerSyncOperation::enter&&c.native_site==0x14114BA9FULL&&c.slot_identity==0x80&&c.target_identity==target&&c.critical_section==lock&&c.incoming.rax==y.incoming.rax&&c.incoming.rdx==lock,"genuinely declared old Raw2 primitive DTO");Monstey_Put(y.image,0,0x300,y.declared.rdx);Monstey_Put(y.expected,0,0x300,y.declared.rdx);return Monstey_GadbBufferedResult{actualOldRax,y.declared.rdx};};const auto n=x.Monstey_Call(guard,lock);const auto o=Monstey_GadbConstructManagerGuard(y.Monstey_Memory(),guard,lock,y.incoming,y.bindings,old);Monstey_Check(o.rax==n.raw.rax&&o.rdx==n.raw.rdx&&x.image==y.image,"old Raw2 subset and full memory equal without adapting new service");y.Monstey_CompareImage();x.Monstey_Finish(n,guard,x.declared);}}
int main(int argc,char **argv){Monstey_Json report=Monstey_Json::object();int code=0;try{Monstey_Check(argc==2,"report path required");Monstey_NormalCases();Monstey_FirstFaultCases();Monstey_ExceptionCases();Monstey_CurrentCases();Monstey_OldProjectionCases();report["status"]="PASS";}catch(const std::exception &e){report["status"]="FAIL";report["error"]=e.what();code=1;}catch(...){report["status"]="FAIL";report["error"]="unexpected nonstandard exception";code=1;}report["scope"]="ADDITIVE_GUARD_GP01_GP04_OWNED_IMAGE_ONLY";report["cases"]=Monstey_Rows.size();report["checks"]=Monstey_Checks;report["whole_images"]=Monstey_Images;report["whole_image_bytes"]=Monstey_Bytes;report["rows"]=Monstey_Rows;report["exception_identity_scope"]="declared dynamic type and shared owned token identity/value/label, not exception_ptr representation or physical exception object address";report["retirement_scope"]="real destructor writes observable by caller return; no claim distinguishing callback-end from function-exit retention in this single-call body";report["OP_NEG_parent_claim"]=false;report["reference_CPP_tests_read"]=false;report["original_OS_physical_ABI_claim"]=false;if(argc>1){std::ofstream file(argv[1],std::ios::binary);file<<report.dump(2)<<'\n';}std::cout<<report.at("status").as_string()<<" cases="<<Monstey_Rows.size()<<" checks="<<Monstey_Checks<<'\n';if(report.contains("error"))std::cerr<<report.at("error").as_string()<<'\n';return code;}
